SELECT
    COUNT(a."atom_id") AS "total_atoms"
FROM "atom" AS a
WHERE a."molecule_id" IN (
    /* Молекулы с тройной связью */
    SELECT DISTINCT b."molecule_id"
    FROM "bond" AS b
    WHERE b."bond_type" = '#'
)
AND a."molecule_id" IN (
    /* Молекулы с фосфором или бромом */
    SELECT DISTINCT a2."molecule_id"
    FROM "atom" AS a2
    WHERE a2."element" IN ('p', 'br')
);

/* Набор с максимальным числом карт */
SELECT
  "s"."id"
FROM "sets" AS "s"
WHERE "s"."basesetsize" = (
  SELECT MAX("s2"."basesetsize")
  FROM "sets" AS "s2"
)
LIMIT 1;

/* Найти набор Commander с максимальным totalsetsize и вернуть его id */
SELECT "s"."id"
FROM "sets" AS "s"
WHERE "s"."type" = 'commander'
  AND "s"."totalsetsize" = (
    SELECT MAX("s2"."totalsetsize")
    FROM "sets" AS "s2"
    WHERE "s2"."type" = 'commander'
  );

/* Найти дату создания аккаунта пользователя IrishStat */
SELECT
  "u"."creationdate"
FROM "users" AS "u"
WHERE "u"."displayname" = 'IrishStat';
